# v583 The Glyph Wheel remastered to the owner's concept art ("Something like this", "Yes remaster it", "Max glow effects"): every
# prize a saturated neon wedge (purple, green, orange, cyan, magenta, gold, teal...) with a bright edge, a big glowing glyph, the prize
# icon and its amount; a double neon rim (cyan inside magenta) with runes and tick marks; a gold pointer with a halo ring; a chrome
# lever with a glass base; a gradient "The glyphs are aligning…" headline; glowing prize chips. Glow everywhere, but the wedges are
# drawn once into an offscreen canvas, so it costs nothing per frame.
import sys, re
P = sys.argv[1] if len(sys.argv) > 1 else 'docs/index.html'
s = open(P, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (c, a[:90]); s = s.replace(a, b)
# the wedges
i = s.index('  const prize = whlCv(px, (x, R) => { for (let i = 0; i < N; i++) {'); j = s.index('  const ringB = whlCv(px, (x, R) =>', i)
s = s[:i] + r'''  const SEG = ["#a43dff", "#19d66a", "#ff9a1a", "#169cff", "#ff3da0", "#ffd21f", "#00d6c8", "#ff5a2a", "#7a5cff", "#3dff9a"]; /* v583 neon wedges */
  const prize = whlCv(px, (x, R) => { const r0 = R * .5, r1 = R * .86;
    for (let i = 0; i < N; i++) { const W = WHEEL[i], c = W.jack === 2 ? "#ff3df0" : W.jack ? "#ffc21a" : SEG[i % SEG.length], a0 = -Math.PI / 2 + i * st, a1 = a0 + st, g = x.createRadialGradient(0, 0, r0, 0, 0, r1);
      g.addColorStop(0, c + "38"); g.addColorStop(.45, c + "a8"); g.addColorStop(.85, c + "e6"); g.addColorStop(1, c); x.fillStyle = g; x.beginPath(); x.arc(0, 0, r1, a0, a1); x.arc(0, 0, r0, a1, a0, true); x.closePath(); x.fill();
      /* a dark inner bevel so each wedge reads as a lit glass tile */
      x.save(); x.clip(); const sh = x.createRadialGradient(0, 0, r0, 0, 0, r1); sh.addColorStop(0, "rgba(0,0,10,.55)"); sh.addColorStop(.35, "rgba(0,0,10,0)"); sh.addColorStop(.9, "rgba(255,255,255,0)"); sh.addColorStop(1, "rgba(255,255,255,.35)"); x.fillStyle = sh; x.fillRect(-R, -R, 2 * R, 2 * R); x.restore();
      x.save(); x.lineWidth = R * .009; x.strokeStyle = c; x.shadowColor = c; x.shadowBlur = R * .06; x.beginPath(); x.arc(0, 0, r1 - R * .006, a0 + .01, a1 - .01); x.arc(0, 0, r0 + R * .006, a1 - .01, a0 + .01, true); x.closePath(); x.stroke();
      x.lineWidth = R * .0035; x.strokeStyle = "rgba(255,255,255,.85)"; x.shadowBlur = R * .02; x.stroke(); x.restore(); }
    x.lineWidth = R * .012; x.shadowColor = "#ffe7a0"; x.shadowBlur = R * .05; x.strokeStyle = "#ffe9b0"; for (const r of [.5, .86]) { x.beginPath(); x.arc(0, 0, R * r, 0, TAU); x.stroke(); }
    x.lineWidth = R * .006; x.strokeStyle = "rgba(255,240,200,.95)"; for (let i = 0; i < N; i++) { const a = -Math.PI / 2 + i * st; x.beginPath(); x.moveTo(Math.cos(a) * r0, Math.sin(a) * r0); x.lineTo(Math.cos(a) * r1, Math.sin(a) * r1); x.stroke(); }
    for (let i = 0; i < N; i++) { const W = WHEEL[i], c = W.jack === 2 ? "#ff3df0" : W.jack ? "#ffc21a" : SEG[i % SEG.length]; x.save(); x.rotate(i * st + st / 2);
      for (const [b, a] of [[R * .09, 1], [R * .03, 1]]) { x.shadowColor = c; x.shadowBlur = b; x.fillStyle = a === 1 && b > R * .05 ? c : "#ffffff"; x.font = `900 ${R * .1}px serif`; x.fillText(W.g, 0, -R * .785); }
      x.shadowColor = "#000"; x.shadowBlur = R * .02; x.font = `${R * .072}px "Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif`; const ic = W.k === "sh" ? "◆" : W.l.replace(/[0-9+d]+$/, "") || W.l; x.fillStyle = W.k === "sh" ? "#e6b8ff" : "#fff";
      if (W.k === "sh") { x.shadowColor = "#d27bff"; x.shadowBlur = R * .05; x.font = `900 ${R * .07}px Rajdhani, system-ui, sans-serif`; x.fillText("◆", 0, -R * .675); } else x.fillText(ic, 0, -R * .675);
      const amt = W.k === "sh" ? String(W.n) : (W.l.match(/[0-9]+[d+]?$|\+$/) || [""])[0]; if (amt) { x.font = `900 ${R * (W.n >= 100 ? .046 : .056)}px Rajdhani, system-ui, sans-serif`; x.shadowColor = c; x.shadowBlur = R * .04; x.fillStyle = "#ffffff"; x.fillText(amt, 0, -R * .595); }
      if (W.jack) { x.font = `900 ${R * .026}px Rajdhani, system-ui, sans-serif`; x.shadowColor = "#ffcf5a"; x.shadowBlur = R * .04; x.fillStyle = W.jack === 2 ? "#ffd6fb" : "#fff1b0"; x.fillText(W.jack === 2 ? "MEGA" : "JACKPOT", 0, -R * .54); } x.restore(); } });
''' + s[j:]
# the rim: cyan inside magenta, brighter runes, tick marks
rep('const outer = whlCv(px, (x, R) => { x.fillStyle = "rgba(8,28,48,.7)"; ring(x, R, .985, .9); x.lineWidth = R * .006; glow(x, PL.o, R * .03); x.strokeStyle = PL.o; for (const r of [.9, .985]) { x.beginPath(); x.arc(0, 0, R * r, 0, TAU); x.stroke(); }',
    'const outer = whlCv(px, (x, R) => { x.fillStyle = "rgba(10,14,40,.85)"; ring(x, R, .985, .9); x.lineWidth = R * .012; glow(x, PL.o, R * .07); x.strokeStyle = PL.o; x.beginPath(); x.arc(0, 0, R * .9, 0, TAU); x.stroke(); x.stroke(); x.strokeStyle = PL.b2; glow(x, PL.b2, R * .08); x.beginPath(); x.arc(0, 0, R * .985, 0, TAU); x.stroke(); x.stroke(); x.lineWidth = R * .004; x.strokeStyle = "#ffffff"; glow(x, PL.o, R * .02); for (const r of [.9, .985]) { x.beginPath(); x.arc(0, 0, R * r, 0, TAU); x.stroke(); }\n    x.lineWidth = R * .005; for (let i = 0; i < 120; i++) { if (i % 10 > 6) continue; const a = i / 120 * TAU; x.strokeStyle = i % 10 ? "rgba(122,244,255,.85)" : "#ffe7a0"; x.beginPath(); x.moveTo(Math.cos(a) * R * .905, Math.sin(a) * R * .905); x.lineTo(Math.cos(a) * R * (i % 10 ? .918 : .925), Math.sin(a) * R * (i % 10 ? .918 : .925)); x.stroke(); }')
# the pointer: a big gold triangle with a halo ring
rep('x.save(); x.translate(R, R * .03); x.rotate(-A.tick * .5); x.shadowColor = "#ffcf5a"; x.shadowBlur = R * .05; const pg = x.createLinearGradient(0, 0, 0, R * .15); pg.addColorStop(0, "#fff6d0"); pg.addColorStop(1, "#e0981f"); x.fillStyle = pg; x.beginPath(); x.moveTo(-R * .06, 0); x.quadraticCurveTo(0, -R * .02, R * .06, 0); x.lineTo(0, R * .155); x.closePath(); x.fill(); x.shadowBlur = 0; x.fillStyle = "#fff"; x.beginPath(); x.arc(0, R * .03, R * .014, 0, TAU); x.fill(); x.restore(); }',
    'x.save(); x.translate(R, R * .045); { x.save(); x.globalCompositeOperation = "lighter"; x.strokeStyle = `rgba(255,214,110,${(.55 + .35 * pulse).toFixed(2)})`; x.lineWidth = R * .008; x.shadowColor = "#ffcf5a"; x.shadowBlur = R * .08; x.beginPath(); x.ellipse(0, -R * .005, R * .1, R * .026, 0, 0, TAU); x.stroke(); const hg = x.createRadialGradient(0, R * .05, 0, 0, R * .05, R * .18); hg.addColorStop(0, `rgba(255,236,170,${(.5 + .3 * pulse + .4 * win).toFixed(2)})`); hg.addColorStop(1, "rgba(255,200,80,0)"); x.fillStyle = hg; x.beginPath(); x.arc(0, R * .05, R * .18, 0, TAU); x.fill(); x.restore(); }\n'
    '  x.rotate(-A.tick * .5); x.shadowColor = "#ffcf5a"; x.shadowBlur = R * .09; const pg = x.createLinearGradient(0, 0, 0, R * .17); pg.addColorStop(0, "#fffbe6"); pg.addColorStop(.5, "#ffd34a"); pg.addColorStop(1, "#d97a00"); x.fillStyle = pg; x.beginPath(); x.moveTo(-R * .075, 0); x.lineTo(R * .075, 0); x.lineTo(0, R * .17); x.closePath(); x.fill(); x.fill(); x.shadowBlur = 0; x.strokeStyle = "#fff6d0"; x.lineWidth = R * .006; x.stroke(); x.fillStyle = "rgba(255,255,255,.7)"; x.beginPath(); x.moveTo(-R * .04, R * .012); x.lineTo(0, R * .012); x.lineTo(0, R * .12); x.closePath(); x.fill(); x.restore(); }')
# the lever, the headline and the chips
rep('.gwz .gwx>b{font-size:19px;letter-spacing:.02em}', '.gwz .gwx>b{font-size:22px;letter-spacing:.02em;font-style:italic;font-weight:900;background:linear-gradient(180deg,#e9fdff,#7af4ff 55%,#3aa8ff);-webkit-background-clip:text;background-clip:text;color:transparent;filter:drop-shadow(0 0 10px rgba(122,244,255,.75))}.gwz .gwx>small{color:#bfe8ff;letter-spacing:.32em;text-shadow:0 0 8px rgba(122,244,255,.8)}.gwz .gwx #gwnow{text-shadow:0 0 10px currentColor}')
rep('.gwl-base{position:absolute;left:4px;right:4px;bottom:0;height:28px;border-radius:9px;background:linear-gradient(180deg,#1e3a50,#0b1826);border:1px solid rgba(122,244,255,.5);box-shadow:0 0 10px rgba(122,244,255,.25)}',
    '.gwl-base{position:absolute;left:2px;right:2px;bottom:0;height:34px;border-radius:10px;background:linear-gradient(180deg,rgba(150,220,255,.35),rgba(20,50,80,.85) 45%,#081422);border:1px solid rgba(122,244,255,.85);box-shadow:0 0 16px rgba(122,244,255,.6),inset 0 1px 0 rgba(255,255,255,.6)}.gwl-base::after{content:"▽";position:absolute;left:0;right:0;top:7px;text-align:center;color:#7af4ff;font-size:14px;text-shadow:0 0 8px #7af4ff}')
rep('.gwl-rod{position:absolute;left:50%;width:6px;margin-left:-3px;border-radius:3px;background:linear-gradient(90deg,#8aa4b8,#eef6ff,#7d93a6);',
    '.gwl-rod{position:absolute;left:50%;width:9px;margin-left:-4.5px;border-radius:5px;background:linear-gradient(90deg,#5d7286,#ffffff 45%,#c9d8e6 60%,#56697c);box-shadow:0 0 8px rgba(200,240,255,.5);')
rep('.gwl-knob{position:absolute;left:50%;top:calc(var(--p) * 74px);width:30px;height:30px;margin-left:-15px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff 0 8%,#ff6ad5 22%,#b0157d 70%,#5a0840);box-shadow:0 0 14px #ff4fc6,0 3px 8px rgba(0,0,0,.5)}',
    '.gwl-knob{position:absolute;left:50%;top:calc(var(--p) * 74px);width:34px;height:34px;margin-left:-17px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff 0 9%,#ff8ae0 24%,#e01aa0 60%,#6a0850);box-shadow:0 0 22px #ff4fc6,0 0 44px rgba(255,79,198,.55),0 3px 8px rgba(0,0,0,.5)}')
rep('.gwchips{display:flex;flex-wrap:wrap;justify-content:center;gap:5px;margin-top:6px}', '.gwchips{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin-top:8px}.gwz .gwchip{border-radius:999px!important;border:1.5px solid var(--c)!important;background:linear-gradient(180deg,rgba(255,255,255,.08),rgba(0,0,0,.35))!important;box-shadow:0 0 10px color-mix(in srgb,var(--c) 70%,transparent),inset 0 0 8px color-mix(in srgb,var(--c) 35%,transparent)!important}.gwz .gwchip b{color:var(--c);text-shadow:0 0 8px var(--c)}')
s2 = re.sub(r"GAME_V = 582\b", "GAME_V = 583", s); assert s2 != s; s = s2
open(P, 'w', encoding='utf-8').write(s); print('ok')
